	if cfg.Docs.Enabled {
		srv.ServeDocs(server.DocsOptions{
			Spec:     openapiSpec,
			UI:       cfg.Docs.UI,
			Path:     cfg.Docs.Path,
			SpecPath: cfg.Docs.SpecPath,
		})
	}

